  select * from jsonb_to_recordset($acrea_exercises$
[{"slug":"air-squat","labelFr":"Air Squat","labelEn":"Air Squat","categorySlug":"strength","equipmentSlug":"no-equipment","pillarSlug":"strength","difficulty":5,"impactSlug":"eleve","familySlug":"corps-entier","typeSlug":"force","muscleGroupSlugs":["abdos","dos","epaules","fessiers","jambes","pecs"],"programmingStatus":"eligible","movementDescription":"Le squat au poids du corps est le squat de poids du corps fondamental – exécuté sans poids comme un échauffement, un exercice de conditionnement, ou un outil d'enseignement de motif de mouvement. C'est l'exercice de passerelle à toutes les variations de squat chargé. CrossFit popularisé le terme « squat au poids du corps » pour le distinguer des squats pondérés.","startPosition":"Tenez-vous droit avec les pieds à la largeur des épaules, les orteils légèrement tournés.\n- Lève la poitrine, regarde droit devant.\nAsseyez-vous les hanches derrière vous comme si vous allais chercher une chaise derrière vous.","outboundExecution":"Pliez les genoux et baissez les hanches.\nDescendez jusqu'à ce que votre pli de hanche tombe sous le haut de vos genoux (au moins parallèle).\nTraversez votre pied entier – en particulier les talons – pour vous relever.\nSerrez vos fessiers en haut.","returnExecution":"Répétez le nombre de répétitions souhaités. Visez 15 à 50 répétitions comme un exercice de conditionnement ou de échauffement.","adaptedVersion":"Poids du corps\nSquat de la berce\nSquat de gobelet\nSquat sauté\nSquat Sumo\nFente de marche\nMarche de canard\nSquat à large air\nSquat d'air Sumo","tips":"Squat de poids du corps fondamental pour tous les niveaux de fitness\nExcellent échauffement avant les squats chargés\nDéveloppe une endurance quadriceps et fessier\nEnseigne le motif de mouvement squat\nAucun équipement nécessaire — fonctionne n'importe où\nUtilisé en CrossFit, formation militaire et réhabilitation","errors":"Évitez l’élan et conservez une amplitude contrôlée.\nArrêtez l’exercice en cas de douleur articulaire.","isActive":true,"reviewStatus":"valide","translationStatus":"validated","media":[{"kind":"poster","uri":"docs/bibliotheque/strength/no-equipment/air-squat/air-squat-poster.webp","fileName":"air-squat-poster.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":1,"loopCount":null,"sha256":"92bd3cba493c6ee533ad0367fb141bc4869d7b6eb97a1612709bf23fcc08cc83","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"},{"kind":"animation","uri":"docs/bibliotheque/strength/no-equipment/air-squat/air-squat-animate.webp","fileName":"air-squat-animate.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":12,"loopCount":0,"sha256":"e01a2f6f885746ad4878950c77140de81c8088736547b04c9c40e5ab36ed4340","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"}]},{"slug":"burpee","labelFr":"Burpee","labelEn":"Burpee","categorySlug":"cardio","equipmentSlug":"no-equipment","pillarSlug":"cardio","difficulty":7,"impactSlug":"eleve","familySlug":"corps-entier","typeSlug":"cardio","muscleGroupSlugs":["abdos","bras","dos","epaules","fessiers","jambes","pecs"],"programmingStatus":"eligible","movementDescription":"Le burripee est un exercice de conditionnement complet du corps qui combine un squat, la planche, pompe et vertical saut dans un mouvement continu. Il élève rapidement la fréquence cardiaque, développe l'endurance musculaire dans tout le corps, et ne nécessite aucun équipement, en faisant un incontournable de l'entraînement à haute intensité d'intervalle et des séances de conditionnement métabolique.","startPosition":"Commencez par vous tenir debout avec les pieds à la largeur de l'épaule et les bras sur vos côtés.\nAccrochez-vous et placez vos mains sur le sol devant vos pieds, à peu près la largeur des épaules.\nSautez ou marchez les deux pieds en position de planche haute avec votre corps formant une ligne droite de la tête aux talons.","outboundExecution":"Faites une pompe complète en abaissant votre poitrine au sol, puis appuyez sur la position de la planche. Gardez votre sangle abdominale brassé et vos hanches à niveau.\nSautez ou marchez les pieds en avant pour atterrir juste en dehors de vos mains, en revenant à une position de squat bas.\nPoussez sur les talons et propulsez-vous vers le haut dans un saut vertical, en tendant les bras au-dessus de la tête.","returnExecution":"Atterrissez doucement avec vos genoux légèrement pliés, puis tomber immédiatement dans la prochaine répétition. Continuer à bouger pour le temps prescrit ou le nombre de répétition.","adaptedVersion":"La moitié du Burpee (pas de pompe, pas de saut)\nPas de Burpee-Up-pompe\nBurpee marche arrière (impact inférieur)\nSaut de caisson Burpee\nTirage de la Burpee\nBurpee Saut à large portée\nSaut à la tire Burpee\njambe Burpee à une seule personne\nBurpee avec montagnard\nBurpee (avec tirages d'haltères ou presses)","tips":"Incarne l'endurance cardiovasculaire et l'endurance musculaire simultanément\nFonctionne tout le corps : jambes, poitrine, épaules, triceps et sangle abdominale dans chaque répétition\nBrûle un grand nombre de calories par minute\nNécessite aucun équipement et un espace minimal\nFacilement gradué en haut ou en bas en ajustant la vitesse, la profondeur de pompe ou la hauteur de saut\nDéveloppe la ténacité mentale grâce à un effort soutenu de haute intensité","errors":"Ne sacrifiez pas la qualité des appuis à la vitesse.\nArrêtez l’exercice en cas de douleur ou de perte de contrôle.","isActive":true,"reviewStatus":"valide","translationStatus":"validated","media":[{"kind":"poster","uri":"docs/bibliotheque/cardio/no-equipment/burpee/burpee-poster.webp","fileName":"burpee-poster.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":1,"loopCount":null,"sha256":"a9fede02e1366f6c8edec05051abc9d321a8f3088ecd661de7f9b59fa5cbc8e1","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"},{"kind":"animation","uri":"docs/bibliotheque/cardio/no-equipment/burpee/burpee-animate.webp","fileName":"burpee-animate.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":8,"loopCount":0,"sha256":"8ad1cd7144a12febb5176a9fc70d618e6449d2e017d161d0d013be1495ef028e","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"}]},{"slug":"lean-planche","labelFr":"Lean Planche","labelEn":"Lean Planche","categorySlug":"proprioception","equipmentSlug":"no-equipment","pillarSlug":"proprioception","difficulty":8,"impactSlug":"modere","familySlug":"corps-entier","typeSlug":"force","muscleGroupSlugs":["abdos","bras","dos","epaules","fessiers","jambes","pecs"],"programmingStatus":"eligible","movementDescription":"La planche maigre est une progression calisthnique vers la planche complète. De la position pompe, vous penchez votre corps vers l'avant afin que vos épaules passent au-delà de vos mains, en déplaçant votre centre de gravité sur vos paumes. Plus vous penchez, plus la position approche une planche.","startPosition":"Commencez par une position de planche haute avec les mains à la largeur des épaules à l'écart sur le sol.\nTournez légèrement les mains vers l'extérieur (des doigts pointant vers les côtés) pour protéger vos poignets.\nContractez la sangle abdominale. Pressez vos fessiers. Protâchez vos épaules (poussez le sol loin).","outboundExecution":"Penchez votre corps en avant en déplaçant le poids sur vos mains — vos épaules devraient passer au-delà de vos poignets.\nMaintenez les bras droits et une ligne droite du corps.\nMaintenez la position de 10 à 30 secondes.\nAugmentez progressivement le poids avant en quelques semaines.","returnExecution":"Vos pieds deviendront plus légers. Finalement, ils commencent à soulever lorsque vous approchez de l'équilibre de la planche.","adaptedVersion":"Planche complète\nPlanche à étrier\nPlanche à grenouilles (planche à écailles)\nPlanche Lean sur Parallettes\nPseudo Planche Pompe","tips":"Progression de la planification fondamentale\nDéveloppe une force deltoïde antérieure extrême\nDéveloppe le conditionnement du poignet et de l'avant-bras\nDéveloppe la sangle abdominale de soutien sous le maigre avant\nAucun équipement nécessaire\nTremplin essentiel à la planche complète","errors":"Évitez l’élan et conservez une amplitude contrôlée.\nArrêtez l’exercice en cas de douleur articulaire.","isActive":true,"reviewStatus":"valide","translationStatus":"validated","media":[{"kind":"poster","uri":"docs/bibliotheque/proprioception/no-equipment/lean-planche/lean-planche-poster.webp","fileName":"lean-planche-poster.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":1,"loopCount":null,"sha256":"f7203d9145df2d7f1fc503dfe8a25482b0d79f4db7b2eaa116f9318dded0541a","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"},{"kind":"animation","uri":"docs/bibliotheque/proprioception/no-equipment/lean-planche/lean-planche-animate.webp","fileName":"lean-planche-animate.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":8,"loopCount":0,"sha256":"441e663f905266db5bdba8a32e102d324b9453234b45cadaf8f1ea41c565a2d9","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"}]},{"slug":"lying-leg-raise","labelFr":"Lying Leg Raise","labelEn":"Lying Leg Raise","categorySlug":"proprioception","equipmentSlug":"no-equipment","pillarSlug":"proprioception","difficulty":4,"impactSlug":"faible","familySlug":"corps-entier","typeSlug":"force","muscleGroupSlugs":["abdos","bras","dos","fessiers","jambes"],"programmingStatus":"eligible","movementDescription":"Le relèvement de la jambe allongée est un exercice de base où vous vous couchez sur le dos et soulevez les deux jambes droites du sol jusqu'à la verticale (ou aussi près que votre force le permet), puis les baissent sous contrôle. Il développe les abdominaux inférieurs et les flexeurs de hanche, et entraîne la sangle abdominale pour résister à l'arêtement du bas du dos lorsque les jambes descendent.","startPosition":"Allongez-vous à plat sur le dos sur le sol avec vos jambes droites et les bras étendus sur vos côtés, paumes vers le bas.\nPlacez vos mains à plat sous vos fessiers pour un soutien plus bas-dos si nécessaire.\nContractez votre sangle abdominale dur. Appuyez fermement sur votre dos inférieur dans le sol et gardez-le là tout au long de l'série.","outboundExecution":"Relever les deux jambes droites du sol en contractant vos abdos et vos flexeurs de hanche. Gardez vos jambes droites ou avec un léger virage dans les genoux.\nContinuez à soulever jusqu'à ce que vos jambes atteignent la verticale (90 degrés) ou la hauteur que votre portée permet tout en gardant votre dos inférieur enfoncé dans le sol.\nPause brièvement en haut, puis baissez lentement les jambes en bas sous contrôle sur un nombre de deux à trois secondes.\nArrêtez juste avant que vos talons touchent le sol — gardez la tension sur les abdominaux tout au long de l'série.","returnExecution":"Si votre dos inférieur se lève du sol, vous avez baissé trop loin. Réduire la portée jusqu'à ce que vous puissiez maintenir le contact arrière.","adaptedVersion":"Élevée à simple lévrier\nAlternativement jambe jambe\nLevez la hanche du pied\nLevez la jambe torsadée\nLevage de la hanche du pied suspendu (avance)\nLevage de la jambe couchée (régression)\nLevage des jambes pondérales (poids des chevilles)\nRelevé de jambes allongé tempo (4 s de descente)\nLevez la jambe de menthe latérale\nAllonger le haut de la jambe","tips":"Développe les abdos inférieurs et les flexeurs de la hanche\nEntraîne la sangle abdominale pour résister à l'arche bas-arrière\nAucun équipement nécessaire — fonctionne n'importe où\nPlus facile à évaluer que les variations de suspensions\nExcellent accessoire pour ascenseurs composés\nAméliore la flexibilité de la hanche et l'endurance de la sangle abdominale","errors":"Évitez l’élan et conservez une amplitude contrôlée.\nArrêtez l’exercice en cas de douleur articulaire.","isActive":true,"reviewStatus":"valide","translationStatus":"validated","media":[{"kind":"poster","uri":"docs/bibliotheque/proprioception/no-equipment/lying-leg-raise/lying-leg-raise-poster.webp","fileName":"lying-leg-raise-poster.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":1,"loopCount":null,"sha256":"cd4549b6bb1ba954413f09bb560da3f4e1773bed4664de90272c30b3c5dd1553","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"},{"kind":"animation","uri":"docs/bibliotheque/proprioception/no-equipment/lying-leg-raise/lying-leg-raise-animate.webp","fileName":"lying-leg-raise-animate.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":2,"loopCount":0,"sha256":"db4c8b8d235da339b7476bc156281c55cf491831cc3f10193b32bffe093a2c9d","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"}]},{"slug":"mountain-climber","labelFr":"Mountain Climber","labelEn":"Mountain Climber","categorySlug":"cardio","equipmentSlug":"no-equipment","pillarSlug":"cardio","difficulty":6,"impactSlug":"eleve","familySlug":"corps-entier","typeSlug":"cardio","muscleGroupSlugs":["abdos","dos","epaules","fessiers","jambes","pecs"],"programmingStatus":"eligible","movementDescription":"Le grimpeur est un exercice dynamique en position de planche dans lequel vous ramenez rapidement les genoux vers la poitrine en alternance. Il élève vite la fréquence cardiaque et sollicite fortement la sangle abdominale, les fléchisseurs de hanche et les stabilisateurs des épaules. Utilisé en HIIT, à l’échauffement ou dans des circuits métaboliques, il fournit un travail intense en peu de temps.","startPosition":"Commencez par une position de planche haute avec vos mains directement sous vos épaules et votre corps formant une ligne droite de la tête aux talons.\nFaites pression sur votre sangle abdominale et pressez vos fessiers. Vos hanches doivent rester à niveau tout au long du mouvement, et non rebondir de haut en bas.\nRamenez le genou droit vers la poitrine en gardant le pied décollé du sol.","outboundExecution":"Commuter rapidement les jambes : prolonger la jambe droite jusqu'à la position de la planche tout en tirant votre genou gauche vers votre poitrine.\nContinuez à alterner les jambes aussi rapidement que possible tout en maintenant un dos plat et des épaules stables.\nRespirez rythmiquement, expirez sur chaque entraînement du genou. Évitez de laisser vos hanches piquer ou saper.","returnExecution":"Travaillez à intervalles : 20 à 40 secondes de grimpeurs rapides suivis de 10 à 30 secondes de repos, pour plusieurs tours.","adaptedVersion":"Grimpeur lent (tempo contrôlé)\nGrimpeur croisé (genou vers le coude opposé)\nGrimpeur Spiderman (genou vers l’extérieur de la main du même côté)\nGrimpeur avec déplacement latéral\nDéclin de la montagne Grimpeur (pieds surélevés)\nEscalade coulissante de montagne (avec sliders ou serviettes)\nBurpee avec montagnard\nEscalade verticale de montagne\nGrimpeur avec sangles de suspension","tips":"Élevez rapidement la fréquence cardiaque pour le conditionnement cardiovasculaire\nIncline la sangle abdominale (en particulier l'anti-rotation et l'anti-extension) sous fatigue\nDéveloppe l'endurance dans les flexeurs de la hanche et les stabilisateurs d'épaule\nNécessite aucun équipement et un espace minimal\nDoubles comme un échauffement dynamique avant le levage ou le sport\nFacilement graduée en changeant de vitesse ou en ajoutant des variations","errors":"Ne sacrifiez pas la qualité des appuis à la vitesse.\nArrêtez l’exercice en cas de douleur ou de perte de contrôle.","isActive":true,"reviewStatus":"valide","translationStatus":"validated","media":[{"kind":"poster","uri":"docs/bibliotheque/cardio/no-equipment/mountain-climber/mountain-climber-poster.webp","fileName":"mountain-climber-poster.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":1,"loopCount":null,"sha256":"fd1a4ab00c41dce401a0bfc2a32cd1b1bbda4be8138393cc7a0c7d0c5f9f08fc","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"},{"kind":"animation","uri":"docs/bibliotheque/cardio/no-equipment/mountain-climber/mountain-climber-animate.webp","fileName":"mountain-climber-animate.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":6,"loopCount":0,"sha256":"1b52d7eb7da14f1847a7da29c73616ea136b63fc64aadebe39f592566c7c8589","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"}]},{"slug":"push-up","labelFr":"Pompe","labelEn":"Push-up","categorySlug":"strength","equipmentSlug":"no-equipment","pillarSlug":"strength","difficulty":7,"impactSlug":"modere","familySlug":"corps-entier","typeSlug":"force","muscleGroupSlugs":["abdos","bras","dos","epaules","fessiers","jambes","pecs"],"programmingStatus":"eligible","movementDescription":"La pompe est l’exercice fondamental de poussée du haut du corps au poids du corps. Depuis une planche haute, abaissez la poitrine vers le sol puis poussez pour revenir en position de départ. Cette fiche décrit la pompe standard, distincte de ses nombreuses variantes.","startPosition":"Placez-vous en planche haute, les mains légèrement plus écartées que les épaules et les doigts dirigés vers l’avant.\nFormez une ligne droite des talons à la tête en engageant la sangle abdominale et les fessiers.\nFléchissez les coudes pour descendre la poitrine vers le sol.","outboundExecution":"Gardez les coudes à environ 45 degrés du buste.\nTouchez le sol avec la poitrine, ou approchez-vous à quelques centimètres selon votre mobilité.\nPoussez dans les mains jusqu’à tendre les bras, sans perdre l’alignement du corps.","returnExecution":"Réalisez 10 à 25 répétitions par série selon votre niveau.","adaptedVersion":"Pompe sur les genoux.\nPompe diamant.\nPompe inclinée.\nPompe déclinée.\nPompe archer.","tips":"Développe la force des pectoraux, des triceps et des épaules.\nRenforce le gainage et la stabilité des épaules.\nNe nécessite aucun matériel et peut se pratiquer partout.\nSe décline facilement en variantes plus simples ou plus difficiles.","errors":"Gardez la nuque neutre et le tronc gainé pendant tout le mouvement.\nRéduisez l'amplitude ou choisissez une variante inclinée si le bas du dos ou les épaules compensent.\nArrêtez l'exercice en cas de douleur aiguë au poignet, au coude ou à l'épaule.","isActive":true,"reviewStatus":"valide","translationStatus":"validated","media":[{"kind":"poster","uri":"docs/bibliotheque/strength/no-equipment/push-up/push-up-poster.webp","fileName":"push-up-poster.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":1,"loopCount":null,"sha256":"5d4d7094ae5a0c470f8eec6869a3ced8f55fb3b8b76f18debcbb8a1920dd61da","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"},{"kind":"animation","uri":"docs/bibliotheque/strength/no-equipment/push-up/push-up-animate.webp","fileName":"push-up-animate.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":12,"loopCount":0,"sha256":"0c09953f530a7864ca95f766f7d0bc301824d14c6f3bcf806a2363efc2b6f632","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"}]}]
$acrea_exercises$::jsonb) as value(slug text, "muscleGroupSlugs" jsonb, media jsonb)
)
insert into public.catalog_exercise_muscle_groups (exercise_id, muscle_group_id)
select exercise.id, muscle_group.id
from exercise_seed value
join public.catalog_exercises exercise on exercise.slug = value.slug
cross join lateral jsonb_array_elements_text(value."muscleGroupSlugs") muscle(code)
join public.catalog_muscle_groups muscle_group on muscle_group.code = muscle.code;

with exercise_seed as (
  select * from jsonb_to_recordset($acrea_exercises$
[{"slug":"air-squat","labelFr":"Air Squat","labelEn":"Air Squat","categorySlug":"strength","equipmentSlug":"no-equipment","pillarSlug":"strength","difficulty":5,"impactSlug":"eleve","familySlug":"corps-entier","typeSlug":"force","muscleGroupSlugs":["abdos","dos","epaules","fessiers","jambes","pecs"],"programmingStatus":"eligible","movementDescription":"Le squat au poids du corps est le squat de poids du corps fondamental – exécuté sans poids comme un échauffement, un exercice de conditionnement, ou un outil d'enseignement de motif de mouvement. C'est l'exercice de passerelle à toutes les variations de squat chargé. CrossFit popularisé le terme « squat au poids du corps » pour le distinguer des squats pondérés.","startPosition":"Tenez-vous droit avec les pieds à la largeur des épaules, les orteils légèrement tournés.\n- Lève la poitrine, regarde droit devant.\nAsseyez-vous les hanches derrière vous comme si vous allais chercher une chaise derrière vous.","outboundExecution":"Pliez les genoux et baissez les hanches.\nDescendez jusqu'à ce que votre pli de hanche tombe sous le haut de vos genoux (au moins parallèle).\nTraversez votre pied entier – en particulier les talons – pour vous relever.\nSerrez vos fessiers en haut.","returnExecution":"Répétez le nombre de répétitions souhaités. Visez 15 à 50 répétitions comme un exercice de conditionnement ou de échauffement.","adaptedVersion":"Poids du corps\nSquat de la berce\nSquat de gobelet\nSquat sauté\nSquat Sumo\nFente de marche\nMarche de canard\nSquat à large air\nSquat d'air Sumo","tips":"Squat de poids du corps fondamental pour tous les niveaux de fitness\nExcellent échauffement avant les squats chargés\nDéveloppe une endurance quadriceps et fessier\nEnseigne le motif de mouvement squat\nAucun équipement nécessaire — fonctionne n'importe où\nUtilisé en CrossFit, formation militaire et réhabilitation","errors":"Évitez l’élan et conservez une amplitude contrôlée.\nArrêtez l’exercice en cas de douleur articulaire.","isActive":true,"reviewStatus":"valide","translationStatus":"validated","media":[{"kind":"poster","uri":"docs/bibliotheque/strength/no-equipment/air-squat/air-squat-poster.webp","fileName":"air-squat-poster.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":1,"loopCount":null,"sha256":"92bd3cba493c6ee533ad0367fb141bc4869d7b6eb97a1612709bf23fcc08cc83","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"},{"kind":"animation","uri":"docs/bibliotheque/strength/no-equipment/air-squat/air-squat-animate.webp","fileName":"air-squat-animate.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":12,"loopCount":0,"sha256":"e01a2f6f885746ad4878950c77140de81c8088736547b04c9c40e5ab36ed4340","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"}]},{"slug":"burpee","labelFr":"Burpee","labelEn":"Burpee","categorySlug":"cardio","equipmentSlug":"no-equipment","pillarSlug":"cardio","difficulty":7,"impactSlug":"eleve","familySlug":"corps-entier","typeSlug":"cardio","muscleGroupSlugs":["abdos","bras","dos","epaules","fessiers","jambes","pecs"],"programmingStatus":"eligible","movementDescription":"Le burripee est un exercice de conditionnement complet du corps qui combine un squat, la planche, pompe et vertical saut dans un mouvement continu. Il élève rapidement la fréquence cardiaque, développe l'endurance musculaire dans tout le corps, et ne nécessite aucun équipement, en faisant un incontournable de l'entraînement à haute intensité d'intervalle et des séances de conditionnement métabolique.","startPosition":"Commencez par vous tenir debout avec les pieds à la largeur de l'épaule et les bras sur vos côtés.\nAccrochez-vous et placez vos mains sur le sol devant vos pieds, à peu près la largeur des épaules.\nSautez ou marchez les deux pieds en position de planche haute avec votre corps formant une ligne droite de la tête aux talons.","outboundExecution":"Faites une pompe complète en abaissant votre poitrine au sol, puis appuyez sur la position de la planche. Gardez votre sangle abdominale brassé et vos hanches à niveau.\nSautez ou marchez les pieds en avant pour atterrir juste en dehors de vos mains, en revenant à une position de squat bas.\nPoussez sur les talons et propulsez-vous vers le haut dans un saut vertical, en tendant les bras au-dessus de la tête.","returnExecution":"Atterrissez doucement avec vos genoux légèrement pliés, puis tomber immédiatement dans la prochaine répétition. Continuer à bouger pour le temps prescrit ou le nombre de répétition.","adaptedVersion":"La moitié du Burpee (pas de pompe, pas de saut)\nPas de Burpee-Up-pompe\nBurpee marche arrière (impact inférieur)\nSaut de caisson Burpee\nTirage de la Burpee\nBurpee Saut à large portée\nSaut à la tire Burpee\njambe Burpee à une seule personne\nBurpee avec montagnard\nBurpee (avec tirages d'haltères ou presses)","tips":"Incarne l'endurance cardiovasculaire et l'endurance musculaire simultanément\nFonctionne tout le corps : jambes, poitrine, épaules, triceps et sangle abdominale dans chaque répétition\nBrûle un grand nombre de calories par minute\nNécessite aucun équipement et un espace minimal\nFacilement gradué en haut ou en bas en ajustant la vitesse, la profondeur de pompe ou la hauteur de saut\nDéveloppe la ténacité mentale grâce à un effort soutenu de haute intensité","errors":"Ne sacrifiez pas la qualité des appuis à la vitesse.\nArrêtez l’exercice en cas de douleur ou de perte de contrôle.","isActive":true,"reviewStatus":"valide","translationStatus":"validated","media":[{"kind":"poster","uri":"docs/bibliotheque/cardio/no-equipment/burpee/burpee-poster.webp","fileName":"burpee-poster.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":1,"loopCount":null,"sha256":"a9fede02e1366f6c8edec05051abc9d321a8f3088ecd661de7f9b59fa5cbc8e1","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"},{"kind":"animation","uri":"docs/bibliotheque/cardio/no-equipment/burpee/burpee-animate.webp","fileName":"burpee-animate.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":8,"loopCount":0,"sha256":"8ad1cd7144a12febb5176a9fc70d618e6449d2e017d161d0d013be1495ef028e","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"}]},{"slug":"lean-planche","labelFr":"Lean Planche","labelEn":"Lean Planche","categorySlug":"proprioception","equipmentSlug":"no-equipment","pillarSlug":"proprioception","difficulty":8,"impactSlug":"modere","familySlug":"corps-entier","typeSlug":"force","muscleGroupSlugs":["abdos","bras","dos","epaules","fessiers","jambes","pecs"],"programmingStatus":"eligible","movementDescription":"La planche maigre est une progression calisthnique vers la planche complète. De la position pompe, vous penchez votre corps vers l'avant afin que vos épaules passent au-delà de vos mains, en déplaçant votre centre de gravité sur vos paumes. Plus vous penchez, plus la position approche une planche.","startPosition":"Commencez par une position de planche haute avec les mains à la largeur des épaules à l'écart sur le sol.\nTournez légèrement les mains vers l'extérieur (des doigts pointant vers les côtés) pour protéger vos poignets.\nContractez la sangle abdominale. Pressez vos fessiers. Protâchez vos épaules (poussez le sol loin).","outboundExecution":"Penchez votre corps en avant en déplaçant le poids sur vos mains — vos épaules devraient passer au-delà de vos poignets.\nMaintenez les bras droits et une ligne droite du corps.\nMaintenez la position de 10 à 30 secondes.\nAugmentez progressivement le poids avant en quelques semaines.","returnExecution":"Vos pieds deviendront plus légers. Finalement, ils commencent à soulever lorsque vous approchez de l'équilibre de la planche.","adaptedVersion":"Planche complète\nPlanche à étrier\nPlanche à grenouilles (planche à écailles)\nPlanche Lean sur Parallettes\nPseudo Planche Pompe","tips":"Progression de la planification fondamentale\nDéveloppe une force deltoïde antérieure extrême\nDéveloppe le conditionnement du poignet et de l'avant-bras\nDéveloppe la sangle abdominale de soutien sous le maigre avant\nAucun équipement nécessaire\nTremplin essentiel à la planche complète","errors":"Évitez l’élan et conservez une amplitude contrôlée.\nArrêtez l’exercice en cas de douleur articulaire.","isActive":true,"reviewStatus":"valide","translationStatus":"validated","media":[{"kind":"poster","uri":"docs/bibliotheque/proprioception/no-equipment/lean-planche/lean-planche-poster.webp","fileName":"lean-planche-poster.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":1,"loopCount":null,"sha256":"f7203d9145df2d7f1fc503dfe8a25482b0d79f4db7b2eaa116f9318dded0541a","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"},{"kind":"animation","uri":"docs/bibliotheque/proprioception/no-equipment/lean-planche/lean-planche-animate.webp","fileName":"lean-planche-animate.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":8,"loopCount":0,"sha256":"441e663f905266db5bdba8a32e102d324b9453234b45cadaf8f1ea41c565a2d9","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"}]},{"slug":"lying-leg-raise","labelFr":"Lying Leg Raise","labelEn":"Lying Leg Raise","categorySlug":"proprioception","equipmentSlug":"no-equipment","pillarSlug":"proprioception","difficulty":4,"impactSlug":"faible","familySlug":"corps-entier","typeSlug":"force","muscleGroupSlugs":["abdos","bras","dos","fessiers","jambes"],"programmingStatus":"eligible","movementDescription":"Le relèvement de la jambe allongée est un exercice de base où vous vous couchez sur le dos et soulevez les deux jambes droites du sol jusqu'à la verticale (ou aussi près que votre force le permet), puis les baissent sous contrôle. Il développe les abdominaux inférieurs et les flexeurs de hanche, et entraîne la sangle abdominale pour résister à l'arêtement du bas du dos lorsque les jambes descendent.","startPosition":"Allongez-vous à plat sur le dos sur le sol avec vos jambes droites et les bras étendus sur vos côtés, paumes vers le bas.\nPlacez vos mains à plat sous vos fessiers pour un soutien plus bas-dos si nécessaire.\nContractez votre sangle abdominale dur. Appuyez fermement sur votre dos inférieur dans le sol et gardez-le là tout au long de l'série.","outboundExecution":"Relever les deux jambes droites du sol en contractant vos abdos et vos flexeurs de hanche. Gardez vos jambes droites ou avec un léger virage dans les genoux.\nContinuez à soulever jusqu'à ce que vos jambes atteignent la verticale (90 degrés) ou la hauteur que votre portée permet tout en gardant votre dos inférieur enfoncé dans le sol.\nPause brièvement en haut, puis baissez lentement les jambes en bas sous contrôle sur un nombre de deux à trois secondes.\nArrêtez juste avant que vos talons touchent le sol — gardez la tension sur les abdominaux tout au long de l'série.","returnExecution":"Si votre dos inférieur se lève du sol, vous avez baissé trop loin. Réduire la portée jusqu'à ce que vous puissiez maintenir le contact arrière.","adaptedVersion":"Élevée à simple lévrier\nAlternativement jambe jambe\nLevez la hanche du pied\nLevez la jambe torsadée\nLevage de la hanche du pied suspendu (avance)\nLevage de la jambe couchée (régression)\nLevage des jambes pondérales (poids des chevilles)\nRelevé de jambes allongé tempo (4 s de descente)\nLevez la jambe de menthe latérale\nAllonger le haut de la jambe","tips":"Développe les abdos inférieurs et les flexeurs de la hanche\nEntraîne la sangle abdominale pour résister à l'arche bas-arrière\nAucun équipement nécessaire — fonctionne n'importe où\nPlus facile à évaluer que les variations de suspensions\nExcellent accessoire pour ascenseurs composés\nAméliore la flexibilité de la hanche et l'endurance de la sangle abdominale","errors":"Évitez l’élan et conservez une amplitude contrôlée.\nArrêtez l’exercice en cas de douleur articulaire.","isActive":true,"reviewStatus":"valide","translationStatus":"validated","media":[{"kind":"poster","uri":"docs/bibliotheque/proprioception/no-equipment/lying-leg-raise/lying-leg-raise-poster.webp","fileName":"lying-leg-raise-poster.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":1,"loopCount":null,"sha256":"cd4549b6bb1ba954413f09bb560da3f4e1773bed4664de90272c30b3c5dd1553","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"},{"kind":"animation","uri":"docs/bibliotheque/proprioception/no-equipment/lying-leg-raise/lying-leg-raise-animate.webp","fileName":"lying-leg-raise-animate.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":2,"loopCount":0,"sha256":"db4c8b8d235da339b7476bc156281c55cf491831cc3f10193b32bffe093a2c9d","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"}]},{"slug":"mountain-climber","labelFr":"Mountain Climber","labelEn":"Mountain Climber","categorySlug":"cardio","equipmentSlug":"no-equipment","pillarSlug":"cardio","difficulty":6,"impactSlug":"eleve","familySlug":"corps-entier","typeSlug":"cardio","muscleGroupSlugs":["abdos","dos","epaules","fessiers","jambes","pecs"],"programmingStatus":"eligible","movementDescription":"Le grimpeur est un exercice dynamique en position de planche dans lequel vous ramenez rapidement les genoux vers la poitrine en alternance. Il élève vite la fréquence cardiaque et sollicite fortement la sangle abdominale, les fléchisseurs de hanche et les stabilisateurs des épaules. Utilisé en HIIT, à l’échauffement ou dans des circuits métaboliques, il fournit un travail intense en peu de temps.","startPosition":"Commencez par une position de planche haute avec vos mains directement sous vos épaules et votre corps formant une ligne droite de la tête aux talons.\nFaites pression sur votre sangle abdominale et pressez vos fessiers. Vos hanches doivent rester à niveau tout au long du mouvement, et non rebondir de haut en bas.\nRamenez le genou droit vers la poitrine en gardant le pied décollé du sol.","outboundExecution":"Commuter rapidement les jambes : prolonger la jambe droite jusqu'à la position de la planche tout en tirant votre genou gauche vers votre poitrine.\nContinuez à alterner les jambes aussi rapidement que possible tout en maintenant un dos plat et des épaules stables.\nRespirez rythmiquement, expirez sur chaque entraînement du genou. Évitez de laisser vos hanches piquer ou saper.","returnExecution":"Travaillez à intervalles : 20 à 40 secondes de grimpeurs rapides suivis de 10 à 30 secondes de repos, pour plusieurs tours.","adaptedVersion":"Grimpeur lent (tempo contrôlé)\nGrimpeur croisé (genou vers le coude opposé)\nGrimpeur Spiderman (genou vers l’extérieur de la main du même côté)\nGrimpeur avec déplacement latéral\nDéclin de la montagne Grimpeur (pieds surélevés)\nEscalade coulissante de montagne (avec sliders ou serviettes)\nBurpee avec montagnard\nEscalade verticale de montagne\nGrimpeur avec sangles de suspension","tips":"Élevez rapidement la fréquence cardiaque pour le conditionnement cardiovasculaire\nIncline la sangle abdominale (en particulier l'anti-rotation et l'anti-extension) sous fatigue\nDéveloppe l'endurance dans les flexeurs de la hanche et les stabilisateurs d'épaule\nNécessite aucun équipement et un espace minimal\nDoubles comme un échauffement dynamique avant le levage ou le sport\nFacilement graduée en changeant de vitesse ou en ajoutant des variations","errors":"Ne sacrifiez pas la qualité des appuis à la vitesse.\nArrêtez l’exercice en cas de douleur ou de perte de contrôle.","isActive":true,"reviewStatus":"valide","translationStatus":"validated","media":[{"kind":"poster","uri":"docs/bibliotheque/cardio/no-equipment/mountain-climber/mountain-climber-poster.webp","fileName":"mountain-climber-poster.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":1,"loopCount":null,"sha256":"fd1a4ab00c41dce401a0bfc2a32cd1b1bbda4be8138393cc7a0c7d0c5f9f08fc","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"},{"kind":"animation","uri":"docs/bibliotheque/cardio/no-equipment/mountain-climber/mountain-climber-animate.webp","fileName":"mountain-climber-animate.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":6,"loopCount":0,"sha256":"1b52d7eb7da14f1847a7da29c73616ea136b63fc64aadebe39f592566c7c8589","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"}]},{"slug":"push-up","labelFr":"Pompe","labelEn":"Push-up","categorySlug":"strength","equipmentSlug":"no-equipment","pillarSlug":"strength","difficulty":7,"impactSlug":"modere","familySlug":"corps-entier","typeSlug":"force","muscleGroupSlugs":["abdos","bras","dos","epaules","fessiers","jambes","pecs"],"programmingStatus":"eligible","movementDescription":"La pompe est l’exercice fondamental de poussée du haut du corps au poids du corps. Depuis une planche haute, abaissez la poitrine vers le sol puis poussez pour revenir en position de départ. Cette fiche décrit la pompe standard, distincte de ses nombreuses variantes.","startPosition":"Placez-vous en planche haute, les mains légèrement plus écartées que les épaules et les doigts dirigés vers l’avant.\nFormez une ligne droite des talons à la tête en engageant la sangle abdominale et les fessiers.\nFléchissez les coudes pour descendre la poitrine vers le sol.","outboundExecution":"Gardez les coudes à environ 45 degrés du buste.\nTouchez le sol avec la poitrine, ou approchez-vous à quelques centimètres selon votre mobilité.\nPoussez dans les mains jusqu’à tendre les bras, sans perdre l’alignement du corps.","returnExecution":"Réalisez 10 à 25 répétitions par série selon votre niveau.","adaptedVersion":"Pompe sur les genoux.\nPompe diamant.\nPompe inclinée.\nPompe déclinée.\nPompe archer.","tips":"Développe la force des pectoraux, des triceps et des épaules.\nRenforce le gainage et la stabilité des épaules.\nNe nécessite aucun matériel et peut se pratiquer partout.\nSe décline facilement en variantes plus simples ou plus difficiles.","errors":"Gardez la nuque neutre et le tronc gainé pendant tout le mouvement.\nRéduisez l'amplitude ou choisissez une variante inclinée si le bas du dos ou les épaules compensent.\nArrêtez l'exercice en cas de douleur aiguë au poignet, au coude ou à l'épaule.","isActive":true,"reviewStatus":"valide","translationStatus":"validated","media":[{"kind":"poster","uri":"docs/bibliotheque/strength/no-equipment/push-up/push-up-poster.webp","fileName":"push-up-poster.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":1,"loopCount":null,"sha256":"5d4d7094ae5a0c470f8eec6869a3ced8f55fb3b8b76f18debcbb8a1920dd61da","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"},{"kind":"animation","uri":"docs/bibliotheque/strength/no-equipment/push-up/push-up-animate.webp","fileName":"push-up-animate.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":12,"loopCount":0,"sha256":"0c09953f530a7864ca95f766f7d0bc301824d14c6f3bcf806a2363efc2b6f632","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"}]}]
$acrea_exercises$::jsonb) as value(slug text, "equipmentSlug" text)
)
insert into public.catalog_exercise_equipment_options (exercise_id, option_index, kind)
select exercise.id, 0,
       case when value."equipmentSlug" = 'no-equipment' then 'bodyweight' else 'equipment' end
from exercise_seed value
join public.catalog_exercises exercise on exercise.slug = value.slug;

with exercise_seed as (
  select * from jsonb_to_recordset($acrea_exercises$
[{"slug":"air-squat","labelFr":"Air Squat","labelEn":"Air Squat","categorySlug":"strength","equipmentSlug":"no-equipment","pillarSlug":"strength","difficulty":5,"impactSlug":"eleve","familySlug":"corps-entier","typeSlug":"force","muscleGroupSlugs":["abdos","dos","epaules","fessiers","jambes","pecs"],"programmingStatus":"eligible","movementDescription":"Le squat au poids du corps est le squat de poids du corps fondamental – exécuté sans poids comme un échauffement, un exercice de conditionnement, ou un outil d'enseignement de motif de mouvement. C'est l'exercice de passerelle à toutes les variations de squat chargé. CrossFit popularisé le terme « squat au poids du corps » pour le distinguer des squats pondérés.","startPosition":"Tenez-vous droit avec les pieds à la largeur des épaules, les orteils légèrement tournés.\n- Lève la poitrine, regarde droit devant.\nAsseyez-vous les hanches derrière vous comme si vous allais chercher une chaise derrière vous.","outboundExecution":"Pliez les genoux et baissez les hanches.\nDescendez jusqu'à ce que votre pli de hanche tombe sous le haut de vos genoux (au moins parallèle).\nTraversez votre pied entier – en particulier les talons – pour vous relever.\nSerrez vos fessiers en haut.","returnExecution":"Répétez le nombre de répétitions souhaités. Visez 15 à 50 répétitions comme un exercice de conditionnement ou de échauffement.","adaptedVersion":"Poids du corps\nSquat de la berce\nSquat de gobelet\nSquat sauté\nSquat Sumo\nFente de marche\nMarche de canard\nSquat à large air\nSquat d'air Sumo","tips":"Squat de poids du corps fondamental pour tous les niveaux de fitness\nExcellent échauffement avant les squats chargés\nDéveloppe une endurance quadriceps et fessier\nEnseigne le motif de mouvement squat\nAucun équipement nécessaire — fonctionne n'importe où\nUtilisé en CrossFit, formation militaire et réhabilitation","errors":"Évitez l’élan et conservez une amplitude contrôlée.\nArrêtez l’exercice en cas de douleur articulaire.","isActive":true,"reviewStatus":"valide","translationStatus":"validated","media":[{"kind":"poster","uri":"docs/bibliotheque/strength/no-equipment/air-squat/air-squat-poster.webp","fileName":"air-squat-poster.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":1,"loopCount":null,"sha256":"92bd3cba493c6ee533ad0367fb141bc4869d7b6eb97a1612709bf23fcc08cc83","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"},{"kind":"animation","uri":"docs/bibliotheque/strength/no-equipment/air-squat/air-squat-animate.webp","fileName":"air-squat-animate.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":12,"loopCount":0,"sha256":"e01a2f6f885746ad4878950c77140de81c8088736547b04c9c40e5ab36ed4340","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"}]},{"slug":"burpee","labelFr":"Burpee","labelEn":"Burpee","categorySlug":"cardio","equipmentSlug":"no-equipment","pillarSlug":"cardio","difficulty":7,"impactSlug":"eleve","familySlug":"corps-entier","typeSlug":"cardio","muscleGroupSlugs":["abdos","bras","dos","epaules","fessiers","jambes","pecs"],"programmingStatus":"eligible","movementDescription":"Le burripee est un exercice de conditionnement complet du corps qui combine un squat, la planche, pompe et vertical saut dans un mouvement continu. Il élève rapidement la fréquence cardiaque, développe l'endurance musculaire dans tout le corps, et ne nécessite aucun équipement, en faisant un incontournable de l'entraînement à haute intensité d'intervalle et des séances de conditionnement métabolique.","startPosition":"Commencez par vous tenir debout avec les pieds à la largeur de l'épaule et les bras sur vos côtés.\nAccrochez-vous et placez vos mains sur le sol devant vos pieds, à peu près la largeur des épaules.\nSautez ou marchez les deux pieds en position de planche haute avec votre corps formant une ligne droite de la tête aux talons.","outboundExecution":"Faites une pompe complète en abaissant votre poitrine au sol, puis appuyez sur la position de la planche. Gardez votre sangle abdominale brassé et vos hanches à niveau.\nSautez ou marchez les pieds en avant pour atterrir juste en dehors de vos mains, en revenant à une position de squat bas.\nPoussez sur les talons et propulsez-vous vers le haut dans un saut vertical, en tendant les bras au-dessus de la tête.","returnExecution":"Atterrissez doucement avec vos genoux légèrement pliés, puis tomber immédiatement dans la prochaine répétition. Continuer à bouger pour le temps prescrit ou le nombre de répétition.","adaptedVersion":"La moitié du Burpee (pas de pompe, pas de saut)\nPas de Burpee-Up-pompe\nBurpee marche arrière (impact inférieur)\nSaut de caisson Burpee\nTirage de la Burpee\nBurpee Saut à large portée\nSaut à la tire Burpee\njambe Burpee à une seule personne\nBurpee avec montagnard\nBurpee (avec tirages d'haltères ou presses)","tips":"Incarne l'endurance cardiovasculaire et l'endurance musculaire simultanément\nFonctionne tout le corps : jambes, poitrine, épaules, triceps et sangle abdominale dans chaque répétition\nBrûle un grand nombre de calories par minute\nNécessite aucun équipement et un espace minimal\nFacilement gradué en haut ou en bas en ajustant la vitesse, la profondeur de pompe ou la hauteur de saut\nDéveloppe la ténacité mentale grâce à un effort soutenu de haute intensité","errors":"Ne sacrifiez pas la qualité des appuis à la vitesse.\nArrêtez l’exercice en cas de douleur ou de perte de contrôle.","isActive":true,"reviewStatus":"valide","translationStatus":"validated","media":[{"kind":"poster","uri":"docs/bibliotheque/cardio/no-equipment/burpee/burpee-poster.webp","fileName":"burpee-poster.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":1,"loopCount":null,"sha256":"a9fede02e1366f6c8edec05051abc9d321a8f3088ecd661de7f9b59fa5cbc8e1","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"},{"kind":"animation","uri":"docs/bibliotheque/cardio/no-equipment/burpee/burpee-animate.webp","fileName":"burpee-animate.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":8,"loopCount":0,"sha256":"8ad1cd7144a12febb5176a9fc70d618e6449d2e017d161d0d013be1495ef028e","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"}]},{"slug":"lean-planche","labelFr":"Lean Planche","labelEn":"Lean Planche","categorySlug":"proprioception","equipmentSlug":"no-equipment","pillarSlug":"proprioception","difficulty":8,"impactSlug":"modere","familySlug":"corps-entier","typeSlug":"force","muscleGroupSlugs":["abdos","bras","dos","epaules","fessiers","jambes","pecs"],"programmingStatus":"eligible","movementDescription":"La planche maigre est une progression calisthnique vers la planche complète. De la position pompe, vous penchez votre corps vers l'avant afin que vos épaules passent au-delà de vos mains, en déplaçant votre centre de gravité sur vos paumes. Plus vous penchez, plus la position approche une planche.","startPosition":"Commencez par une position de planche haute avec les mains à la largeur des épaules à l'écart sur le sol.\nTournez légèrement les mains vers l'extérieur (des doigts pointant vers les côtés) pour protéger vos poignets.\nContractez la sangle abdominale. Pressez vos fessiers. Protâchez vos épaules (poussez le sol loin).","outboundExecution":"Penchez votre corps en avant en déplaçant le poids sur vos mains — vos épaules devraient passer au-delà de vos poignets.\nMaintenez les bras droits et une ligne droite du corps.\nMaintenez la position de 10 à 30 secondes.\nAugmentez progressivement le poids avant en quelques semaines.","returnExecution":"Vos pieds deviendront plus légers. Finalement, ils commencent à soulever lorsque vous approchez de l'équilibre de la planche.","adaptedVersion":"Planche complète\nPlanche à étrier\nPlanche à grenouilles (planche à écailles)\nPlanche Lean sur Parallettes\nPseudo Planche Pompe","tips":"Progression de la planification fondamentale\nDéveloppe une force deltoïde antérieure extrême\nDéveloppe le conditionnement du poignet et de l'avant-bras\nDéveloppe la sangle abdominale de soutien sous le maigre avant\nAucun équipement nécessaire\nTremplin essentiel à la planche complète","errors":"Évitez l’élan et conservez une amplitude contrôlée.\nArrêtez l’exercice en cas de douleur articulaire.","isActive":true,"reviewStatus":"valide","translationStatus":"validated","media":[{"kind":"poster","uri":"docs/bibliotheque/proprioception/no-equipment/lean-planche/lean-planche-poster.webp","fileName":"lean-planche-poster.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":1,"loopCount":null,"sha256":"f7203d9145df2d7f1fc503dfe8a25482b0d79f4db7b2eaa116f9318dded0541a","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"},{"kind":"animation","uri":"docs/bibliotheque/proprioception/no-equipment/lean-planche/lean-planche-animate.webp","fileName":"lean-planche-animate.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":8,"loopCount":0,"sha256":"441e663f905266db5bdba8a32e102d324b9453234b45cadaf8f1ea41c565a2d9","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"}]},{"slug":"lying-leg-raise","labelFr":"Lying Leg Raise","labelEn":"Lying Leg Raise","categorySlug":"proprioception","equipmentSlug":"no-equipment","pillarSlug":"proprioception","difficulty":4,"impactSlug":"faible","familySlug":"corps-entier","typeSlug":"force","muscleGroupSlugs":["abdos","bras","dos","fessiers","jambes"],"programmingStatus":"eligible","movementDescription":"Le relèvement de la jambe allongée est un exercice de base où vous vous couchez sur le dos et soulevez les deux jambes droites du sol jusqu'à la verticale (ou aussi près que votre force le permet), puis les baissent sous contrôle. Il développe les abdominaux inférieurs et les flexeurs de hanche, et entraîne la sangle abdominale pour résister à l'arêtement du bas du dos lorsque les jambes descendent.","startPosition":"Allongez-vous à plat sur le dos sur le sol avec vos jambes droites et les bras étendus sur vos côtés, paumes vers le bas.\nPlacez vos mains à plat sous vos fessiers pour un soutien plus bas-dos si nécessaire.\nContractez votre sangle abdominale dur. Appuyez fermement sur votre dos inférieur dans le sol et gardez-le là tout au long de l'série.","outboundExecution":"Relever les deux jambes droites du sol en contractant vos abdos et vos flexeurs de hanche. Gardez vos jambes droites ou avec un léger virage dans les genoux.\nContinuez à soulever jusqu'à ce que vos jambes atteignent la verticale (90 degrés) ou la hauteur que votre portée permet tout en gardant votre dos inférieur enfoncé dans le sol.\nPause brièvement en haut, puis baissez lentement les jambes en bas sous contrôle sur un nombre de deux à trois secondes.\nArrêtez juste avant que vos talons touchent le sol — gardez la tension sur les abdominaux tout au long de l'série.","returnExecution":"Si votre dos inférieur se lève du sol, vous avez baissé trop loin. Réduire la portée jusqu'à ce que vous puissiez maintenir le contact arrière.","adaptedVersion":"Élevée à simple lévrier\nAlternativement jambe jambe\nLevez la hanche du pied\nLevez la jambe torsadée\nLevage de la hanche du pied suspendu (avance)\nLevage de la jambe couchée (régression)\nLevage des jambes pondérales (poids des chevilles)\nRelevé de jambes allongé tempo (4 s de descente)\nLevez la jambe de menthe latérale\nAllonger le haut de la jambe","tips":"Développe les abdos inférieurs et les flexeurs de la hanche\nEntraîne la sangle abdominale pour résister à l'arche bas-arrière\nAucun équipement nécessaire — fonctionne n'importe où\nPlus facile à évaluer que les variations de suspensions\nExcellent accessoire pour ascenseurs composés\nAméliore la flexibilité de la hanche et l'endurance de la sangle abdominale","errors":"Évitez l’élan et conservez une amplitude contrôlée.\nArrêtez l’exercice en cas de douleur articulaire.","isActive":true,"reviewStatus":"valide","translationStatus":"validated","media":[{"kind":"poster","uri":"docs/bibliotheque/proprioception/no-equipment/lying-leg-raise/lying-leg-raise-poster.webp","fileName":"lying-leg-raise-poster.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":1,"loopCount":null,"sha256":"cd4549b6bb1ba954413f09bb560da3f4e1773bed4664de90272c30b3c5dd1553","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"},{"kind":"animation","uri":"docs/bibliotheque/proprioception/no-equipment/lying-leg-raise/lying-leg-raise-animate.webp","fileName":"lying-leg-raise-animate.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":2,"loopCount":0,"sha256":"db4c8b8d235da339b7476bc156281c55cf491831cc3f10193b32bffe093a2c9d","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"}]},{"slug":"mountain-climber","labelFr":"Mountain Climber","labelEn":"Mountain Climber","categorySlug":"cardio","equipmentSlug":"no-equipment","pillarSlug":"cardio","difficulty":6,"impactSlug":"eleve","familySlug":"corps-entier","typeSlug":"cardio","muscleGroupSlugs":["abdos","dos","epaules","fessiers","jambes","pecs"],"programmingStatus":"eligible","movementDescription":"Le grimpeur est un exercice dynamique en position de planche dans lequel vous ramenez rapidement les genoux vers la poitrine en alternance. Il élève vite la fréquence cardiaque et sollicite fortement la sangle abdominale, les fléchisseurs de hanche et les stabilisateurs des épaules. Utilisé en HIIT, à l’échauffement ou dans des circuits métaboliques, il fournit un travail intense en peu de temps.","startPosition":"Commencez par une position de planche haute avec vos mains directement sous vos épaules et votre corps formant une ligne droite de la tête aux talons.\nFaites pression sur votre sangle abdominale et pressez vos fessiers. Vos hanches doivent rester à niveau tout au long du mouvement, et non rebondir de haut en bas.\nRamenez le genou droit vers la poitrine en gardant le pied décollé du sol.","outboundExecution":"Commuter rapidement les jambes : prolonger la jambe droite jusqu'à la position de la planche tout en tirant votre genou gauche vers votre poitrine.\nContinuez à alterner les jambes aussi rapidement que possible tout en maintenant un dos plat et des épaules stables.\nRespirez rythmiquement, expirez sur chaque entraînement du genou. Évitez de laisser vos hanches piquer ou saper.","returnExecution":"Travaillez à intervalles : 20 à 40 secondes de grimpeurs rapides suivis de 10 à 30 secondes de repos, pour plusieurs tours.","adaptedVersion":"Grimpeur lent (tempo contrôlé)\nGrimpeur croisé (genou vers le coude opposé)\nGrimpeur Spiderman (genou vers l’extérieur de la main du même côté)\nGrimpeur avec déplacement latéral\nDéclin de la montagne Grimpeur (pieds surélevés)\nEscalade coulissante de montagne (avec sliders ou serviettes)\nBurpee avec montagnard\nEscalade verticale de montagne\nGrimpeur avec sangles de suspension","tips":"Élevez rapidement la fréquence cardiaque pour le conditionnement cardiovasculaire\nIncline la sangle abdominale (en particulier l'anti-rotation et l'anti-extension) sous fatigue\nDéveloppe l'endurance dans les flexeurs de la hanche et les stabilisateurs d'épaule\nNécessite aucun équipement et un espace minimal\nDoubles comme un échauffement dynamique avant le levage ou le sport\nFacilement graduée en changeant de vitesse ou en ajoutant des variations","errors":"Ne sacrifiez pas la qualité des appuis à la vitesse.\nArrêtez l’exercice en cas de douleur ou de perte de contrôle.","isActive":true,"reviewStatus":"valide","translationStatus":"validated","media":[{"kind":"poster","uri":"docs/bibliotheque/cardio/no-equipment/mountain-climber/mountain-climber-poster.webp","fileName":"mountain-climber-poster.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":1,"loopCount":null,"sha256":"fd1a4ab00c41dce401a0bfc2a32cd1b1bbda4be8138393cc7a0c7d0c5f9f08fc","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"},{"kind":"animation","uri":"docs/bibliotheque/cardio/no-equipment/mountain-climber/mountain-climber-animate.webp","fileName":"mountain-climber-animate.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":6,"loopCount":0,"sha256":"1b52d7eb7da14f1847a7da29c73616ea136b63fc64aadebe39f592566c7c8589","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"}]},{"slug":"push-up","labelFr":"Pompe","labelEn":"Push-up","categorySlug":"strength","equipmentSlug":"no-equipment","pillarSlug":"strength","difficulty":7,"impactSlug":"modere","familySlug":"corps-entier","typeSlug":"force","muscleGroupSlugs":["abdos","bras","dos","epaules","fessiers","jambes","pecs"],"programmingStatus":"eligible","movementDescription":"La pompe est l’exercice fondamental de poussée du haut du corps au poids du corps. Depuis une planche haute, abaissez la poitrine vers le sol puis poussez pour revenir en position de départ. Cette fiche décrit la pompe standard, distincte de ses nombreuses variantes.","startPosition":"Placez-vous en planche haute, les mains légèrement plus écartées que les épaules et les doigts dirigés vers l’avant.\nFormez une ligne droite des talons à la tête en engageant la sangle abdominale et les fessiers.\nFléchissez les coudes pour descendre la poitrine vers le sol.","outboundExecution":"Gardez les coudes à environ 45 degrés du buste.\nTouchez le sol avec la poitrine, ou approchez-vous à quelques centimètres selon votre mobilité.\nPoussez dans les mains jusqu’à tendre les bras, sans perdre l’alignement du corps.","returnExecution":"Réalisez 10 à 25 répétitions par série selon votre niveau.","adaptedVersion":"Pompe sur les genoux.\nPompe diamant.\nPompe inclinée.\nPompe déclinée.\nPompe archer.","tips":"Développe la force des pectoraux, des triceps et des épaules.\nRenforce le gainage et la stabilité des épaules.\nNe nécessite aucun matériel et peut se pratiquer partout.\nSe décline facilement en variantes plus simples ou plus difficiles.","errors":"Gardez la nuque neutre et le tronc gainé pendant tout le mouvement.\nRéduisez l'amplitude ou choisissez une variante inclinée si le bas du dos ou les épaules compensent.\nArrêtez l'exercice en cas de douleur aiguë au poignet, au coude ou à l'épaule.","isActive":true,"reviewStatus":"valide","translationStatus":"validated","media":[{"kind":"poster","uri":"docs/bibliotheque/strength/no-equipment/push-up/push-up-poster.webp","fileName":"push-up-poster.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":1,"loopCount":null,"sha256":"5d4d7094ae5a0c470f8eec6869a3ced8f55fb3b8b76f18debcbb8a1920dd61da","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"},{"kind":"animation","uri":"docs/bibliotheque/strength/no-equipment/push-up/push-up-animate.webp","fileName":"push-up-animate.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":12,"loopCount":0,"sha256":"0c09953f530a7864ca95f766f7d0bc301824d14c6f3bcf806a2363efc2b6f632","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"}]}]
$acrea_exercises$::jsonb) as value(slug text, "equipmentSlug" text)
)
insert into public.catalog_exercise_equipment_option_items (option_id, equipment_id)
select option.id, equipment.id
from exercise_seed value
join public.catalog_exercises exercise on exercise.slug = value.slug
join public.catalog_exercise_equipment_options option
  on option.exercise_id = exercise.id and option.option_index = 0
join public.catalog_equipment equipment on equipment.code = value."equipmentSlug"
where value."equipmentSlug" <> 'no-equipment';

with exercise_seed as (
  select * from jsonb_to_recordset($acrea_exercises$
[{"slug":"air-squat","labelFr":"Air Squat","labelEn":"Air Squat","categorySlug":"strength","equipmentSlug":"no-equipment","pillarSlug":"strength","difficulty":5,"impactSlug":"eleve","familySlug":"corps-entier","typeSlug":"force","muscleGroupSlugs":["abdos","dos","epaules","fessiers","jambes","pecs"],"programmingStatus":"eligible","movementDescription":"Le squat au poids du corps est le squat de poids du corps fondamental – exécuté sans poids comme un échauffement, un exercice de conditionnement, ou un outil d'enseignement de motif de mouvement. C'est l'exercice de passerelle à toutes les variations de squat chargé. CrossFit popularisé le terme « squat au poids du corps » pour le distinguer des squats pondérés.","startPosition":"Tenez-vous droit avec les pieds à la largeur des épaules, les orteils légèrement tournés.\n- Lève la poitrine, regarde droit devant.\nAsseyez-vous les hanches derrière vous comme si vous allais chercher une chaise derrière vous.","outboundExecution":"Pliez les genoux et baissez les hanches.\nDescendez jusqu'à ce que votre pli de hanche tombe sous le haut de vos genoux (au moins parallèle).\nTraversez votre pied entier – en particulier les talons – pour vous relever.\nSerrez vos fessiers en haut.","returnExecution":"Répétez le nombre de répétitions souhaités. Visez 15 à 50 répétitions comme un exercice de conditionnement ou de échauffement.","adaptedVersion":"Poids du corps\nSquat de la berce\nSquat de gobelet\nSquat sauté\nSquat Sumo\nFente de marche\nMarche de canard\nSquat à large air\nSquat d'air Sumo","tips":"Squat de poids du corps fondamental pour tous les niveaux de fitness\nExcellent échauffement avant les squats chargés\nDéveloppe une endurance quadriceps et fessier\nEnseigne le motif de mouvement squat\nAucun équipement nécessaire — fonctionne n'importe où\nUtilisé en CrossFit, formation militaire et réhabilitation","errors":"Évitez l’élan et conservez une amplitude contrôlée.\nArrêtez l’exercice en cas de douleur articulaire.","isActive":true,"reviewStatus":"valide","translationStatus":"validated","media":[{"kind":"poster","uri":"docs/bibliotheque/strength/no-equipment/air-squat/air-squat-poster.webp","fileName":"air-squat-poster.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":1,"loopCount":null,"sha256":"92bd3cba493c6ee533ad0367fb141bc4869d7b6eb97a1612709bf23fcc08cc83","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"},{"kind":"animation","uri":"docs/bibliotheque/strength/no-equipment/air-squat/air-squat-animate.webp","fileName":"air-squat-animate.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":12,"loopCount":0,"sha256":"e01a2f6f885746ad4878950c77140de81c8088736547b04c9c40e5ab36ed4340","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"}]},{"slug":"burpee","labelFr":"Burpee","labelEn":"Burpee","categorySlug":"cardio","equipmentSlug":"no-equipment","pillarSlug":"cardio","difficulty":7,"impactSlug":"eleve","familySlug":"corps-entier","typeSlug":"cardio","muscleGroupSlugs":["abdos","bras","dos","epaules","fessiers","jambes","pecs"],"programmingStatus":"eligible","movementDescription":"Le burripee est un exercice de conditionnement complet du corps qui combine un squat, la planche, pompe et vertical saut dans un mouvement continu. Il élève rapidement la fréquence cardiaque, développe l'endurance musculaire dans tout le corps, et ne nécessite aucun équipement, en faisant un incontournable de l'entraînement à haute intensité d'intervalle et des séances de conditionnement métabolique.","startPosition":"Commencez par vous tenir debout avec les pieds à la largeur de l'épaule et les bras sur vos côtés.\nAccrochez-vous et placez vos mains sur le sol devant vos pieds, à peu près la largeur des épaules.\nSautez ou marchez les deux pieds en position de planche haute avec votre corps formant une ligne droite de la tête aux talons.","outboundExecution":"Faites une pompe complète en abaissant votre poitrine au sol, puis appuyez sur la position de la planche. Gardez votre sangle abdominale brassé et vos hanches à niveau.\nSautez ou marchez les pieds en avant pour atterrir juste en dehors de vos mains, en revenant à une position de squat bas.\nPoussez sur les talons et propulsez-vous vers le haut dans un saut vertical, en tendant les bras au-dessus de la tête.","returnExecution":"Atterrissez doucement avec vos genoux légèrement pliés, puis tomber immédiatement dans la prochaine répétition. Continuer à bouger pour le temps prescrit ou le nombre de répétition.","adaptedVersion":"La moitié du Burpee (pas de pompe, pas de saut)\nPas de Burpee-Up-pompe\nBurpee marche arrière (impact inférieur)\nSaut de caisson Burpee\nTirage de la Burpee\nBurpee Saut à large portée\nSaut à la tire Burpee\njambe Burpee à une seule personne\nBurpee avec montagnard\nBurpee (avec tirages d'haltères ou presses)","tips":"Incarne l'endurance cardiovasculaire et l'endurance musculaire simultanément\nFonctionne tout le corps : jambes, poitrine, épaules, triceps et sangle abdominale dans chaque répétition\nBrûle un grand nombre de calories par minute\nNécessite aucun équipement et un espace minimal\nFacilement gradué en haut ou en bas en ajustant la vitesse, la profondeur de pompe ou la hauteur de saut\nDéveloppe la ténacité mentale grâce à un effort soutenu de haute intensité","errors":"Ne sacrifiez pas la qualité des appuis à la vitesse.\nArrêtez l’exercice en cas de douleur ou de perte de contrôle.","isActive":true,"reviewStatus":"valide","translationStatus":"validated","media":[{"kind":"poster","uri":"docs/bibliotheque/cardio/no-equipment/burpee/burpee-poster.webp","fileName":"burpee-poster.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":1,"loopCount":null,"sha256":"a9fede02e1366f6c8edec05051abc9d321a8f3088ecd661de7f9b59fa5cbc8e1","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"},{"kind":"animation","uri":"docs/bibliotheque/cardio/no-equipment/burpee/burpee-animate.webp","fileName":"burpee-animate.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":8,"loopCount":0,"sha256":"8ad1cd7144a12febb5176a9fc70d618e6449d2e017d161d0d013be1495ef028e","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"}]},{"slug":"lean-planche","labelFr":"Lean Planche","labelEn":"Lean Planche","categorySlug":"proprioception","equipmentSlug":"no-equipment","pillarSlug":"proprioception","difficulty":8,"impactSlug":"modere","familySlug":"corps-entier","typeSlug":"force","muscleGroupSlugs":["abdos","bras","dos","epaules","fessiers","jambes","pecs"],"programmingStatus":"eligible","movementDescription":"La planche maigre est une progression calisthnique vers la planche complète. De la position pompe, vous penchez votre corps vers l'avant afin que vos épaules passent au-delà de vos mains, en déplaçant votre centre de gravité sur vos paumes. Plus vous penchez, plus la position approche une planche.","startPosition":"Commencez par une position de planche haute avec les mains à la largeur des épaules à l'écart sur le sol.\nTournez légèrement les mains vers l'extérieur (des doigts pointant vers les côtés) pour protéger vos poignets.\nContractez la sangle abdominale. Pressez vos fessiers. Protâchez vos épaules (poussez le sol loin).","outboundExecution":"Penchez votre corps en avant en déplaçant le poids sur vos mains — vos épaules devraient passer au-delà de vos poignets.\nMaintenez les bras droits et une ligne droite du corps.\nMaintenez la position de 10 à 30 secondes.\nAugmentez progressivement le poids avant en quelques semaines.","returnExecution":"Vos pieds deviendront plus légers. Finalement, ils commencent à soulever lorsque vous approchez de l'équilibre de la planche.","adaptedVersion":"Planche complète\nPlanche à étrier\nPlanche à grenouilles (planche à écailles)\nPlanche Lean sur Parallettes\nPseudo Planche Pompe","tips":"Progression de la planification fondamentale\nDéveloppe une force deltoïde antérieure extrême\nDéveloppe le conditionnement du poignet et de l'avant-bras\nDéveloppe la sangle abdominale de soutien sous le maigre avant\nAucun équipement nécessaire\nTremplin essentiel à la planche complète","errors":"Évitez l’élan et conservez une amplitude contrôlée.\nArrêtez l’exercice en cas de douleur articulaire.","isActive":true,"reviewStatus":"valide","translationStatus":"validated","media":[{"kind":"poster","uri":"docs/bibliotheque/proprioception/no-equipment/lean-planche/lean-planche-poster.webp","fileName":"lean-planche-poster.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":1,"loopCount":null,"sha256":"f7203d9145df2d7f1fc503dfe8a25482b0d79f4db7b2eaa116f9318dded0541a","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"},{"kind":"animation","uri":"docs/bibliotheque/proprioception/no-equipment/lean-planche/lean-planche-animate.webp","fileName":"lean-planche-animate.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":8,"loopCount":0,"sha256":"441e663f905266db5bdba8a32e102d324b9453234b45cadaf8f1ea41c565a2d9","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"}]},{"slug":"lying-leg-raise","labelFr":"Lying Leg Raise","labelEn":"Lying Leg Raise","categorySlug":"proprioception","equipmentSlug":"no-equipment","pillarSlug":"proprioception","difficulty":4,"impactSlug":"faible","familySlug":"corps-entier","typeSlug":"force","muscleGroupSlugs":["abdos","bras","dos","fessiers","jambes"],"programmingStatus":"eligible","movementDescription":"Le relèvement de la jambe allongée est un exercice de base où vous vous couchez sur le dos et soulevez les deux jambes droites du sol jusqu'à la verticale (ou aussi près que votre force le permet), puis les baissent sous contrôle. Il développe les abdominaux inférieurs et les flexeurs de hanche, et entraîne la sangle abdominale pour résister à l'arêtement du bas du dos lorsque les jambes descendent.","startPosition":"Allongez-vous à plat sur le dos sur le sol avec vos jambes droites et les bras étendus sur vos côtés, paumes vers le bas.\nPlacez vos mains à plat sous vos fessiers pour un soutien plus bas-dos si nécessaire.\nContractez votre sangle abdominale dur. Appuyez fermement sur votre dos inférieur dans le sol et gardez-le là tout au long de l'série.","outboundExecution":"Relever les deux jambes droites du sol en contractant vos abdos et vos flexeurs de hanche. Gardez vos jambes droites ou avec un léger virage dans les genoux.\nContinuez à soulever jusqu'à ce que vos jambes atteignent la verticale (90 degrés) ou la hauteur que votre portée permet tout en gardant votre dos inférieur enfoncé dans le sol.\nPause brièvement en haut, puis baissez lentement les jambes en bas sous contrôle sur un nombre de deux à trois secondes.\nArrêtez juste avant que vos talons touchent le sol — gardez la tension sur les abdominaux tout au long de l'série.","returnExecution":"Si votre dos inférieur se lève du sol, vous avez baissé trop loin. Réduire la portée jusqu'à ce que vous puissiez maintenir le contact arrière.","adaptedVersion":"Élevée à simple lévrier\nAlternativement jambe jambe\nLevez la hanche du pied\nLevez la jambe torsadée\nLevage de la hanche du pied suspendu (avance)\nLevage de la jambe couchée (régression)\nLevage des jambes pondérales (poids des chevilles)\nRelevé de jambes allongé tempo (4 s de descente)\nLevez la jambe de menthe latérale\nAllonger le haut de la jambe","tips":"Développe les abdos inférieurs et les flexeurs de la hanche\nEntraîne la sangle abdominale pour résister à l'arche bas-arrière\nAucun équipement nécessaire — fonctionne n'importe où\nPlus facile à évaluer que les variations de suspensions\nExcellent accessoire pour ascenseurs composés\nAméliore la flexibilité de la hanche et l'endurance de la sangle abdominale","errors":"Évitez l’élan et conservez une amplitude contrôlée.\nArrêtez l’exercice en cas de douleur articulaire.","isActive":true,"reviewStatus":"valide","translationStatus":"validated","media":[{"kind":"poster","uri":"docs/bibliotheque/proprioception/no-equipment/lying-leg-raise/lying-leg-raise-poster.webp","fileName":"lying-leg-raise-poster.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":1,"loopCount":null,"sha256":"cd4549b6bb1ba954413f09bb560da3f4e1773bed4664de90272c30b3c5dd1553","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"},{"kind":"animation","uri":"docs/bibliotheque/proprioception/no-equipment/lying-leg-raise/lying-leg-raise-animate.webp","fileName":"lying-leg-raise-animate.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":2,"loopCount":0,"sha256":"db4c8b8d235da339b7476bc156281c55cf491831cc3f10193b32bffe093a2c9d","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"}]},{"slug":"mountain-climber","labelFr":"Mountain Climber","labelEn":"Mountain Climber","categorySlug":"cardio","equipmentSlug":"no-equipment","pillarSlug":"cardio","difficulty":6,"impactSlug":"eleve","familySlug":"corps-entier","typeSlug":"cardio","muscleGroupSlugs":["abdos","dos","epaules","fessiers","jambes","pecs"],"programmingStatus":"eligible","movementDescription":"Le grimpeur est un exercice dynamique en position de planche dans lequel vous ramenez rapidement les genoux vers la poitrine en alternance. Il élève vite la fréquence cardiaque et sollicite fortement la sangle abdominale, les fléchisseurs de hanche et les stabilisateurs des épaules. Utilisé en HIIT, à l’échauffement ou dans des circuits métaboliques, il fournit un travail intense en peu de temps.","startPosition":"Commencez par une position de planche haute avec vos mains directement sous vos épaules et votre corps formant une ligne droite de la tête aux talons.\nFaites pression sur votre sangle abdominale et pressez vos fessiers. Vos hanches doivent rester à niveau tout au long du mouvement, et non rebondir de haut en bas.\nRamenez le genou droit vers la poitrine en gardant le pied décollé du sol.","outboundExecution":"Commuter rapidement les jambes : prolonger la jambe droite jusqu'à la position de la planche tout en tirant votre genou gauche vers votre poitrine.\nContinuez à alterner les jambes aussi rapidement que possible tout en maintenant un dos plat et des épaules stables.\nRespirez rythmiquement, expirez sur chaque entraînement du genou. Évitez de laisser vos hanches piquer ou saper.","returnExecution":"Travaillez à intervalles : 20 à 40 secondes de grimpeurs rapides suivis de 10 à 30 secondes de repos, pour plusieurs tours.","adaptedVersion":"Grimpeur lent (tempo contrôlé)\nGrimpeur croisé (genou vers le coude opposé)\nGrimpeur Spiderman (genou vers l’extérieur de la main du même côté)\nGrimpeur avec déplacement latéral\nDéclin de la montagne Grimpeur (pieds surélevés)\nEscalade coulissante de montagne (avec sliders ou serviettes)\nBurpee avec montagnard\nEscalade verticale de montagne\nGrimpeur avec sangles de suspension","tips":"Élevez rapidement la fréquence cardiaque pour le conditionnement cardiovasculaire\nIncline la sangle abdominale (en particulier l'anti-rotation et l'anti-extension) sous fatigue\nDéveloppe l'endurance dans les flexeurs de la hanche et les stabilisateurs d'épaule\nNécessite aucun équipement et un espace minimal\nDoubles comme un échauffement dynamique avant le levage ou le sport\nFacilement graduée en changeant de vitesse ou en ajoutant des variations","errors":"Ne sacrifiez pas la qualité des appuis à la vitesse.\nArrêtez l’exercice en cas de douleur ou de perte de contrôle.","isActive":true,"reviewStatus":"valide","translationStatus":"validated","media":[{"kind":"poster","uri":"docs/bibliotheque/cardio/no-equipment/mountain-climber/mountain-climber-poster.webp","fileName":"mountain-climber-poster.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":1,"loopCount":null,"sha256":"fd1a4ab00c41dce401a0bfc2a32cd1b1bbda4be8138393cc7a0c7d0c5f9f08fc","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"},{"kind":"animation","uri":"docs/bibliotheque/cardio/no-equipment/mountain-climber/mountain-climber-animate.webp","fileName":"mountain-climber-animate.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":6,"loopCount":0,"sha256":"1b52d7eb7da14f1847a7da29c73616ea136b63fc64aadebe39f592566c7c8589","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"}]},{"slug":"push-up","labelFr":"Pompe","labelEn":"Push-up","categorySlug":"strength","equipmentSlug":"no-equipment","pillarSlug":"strength","difficulty":7,"impactSlug":"modere","familySlug":"corps-entier","typeSlug":"force","muscleGroupSlugs":["abdos","bras","dos","epaules","fessiers","jambes","pecs"],"programmingStatus":"eligible","movementDescription":"La pompe est l’exercice fondamental de poussée du haut du corps au poids du corps. Depuis une planche haute, abaissez la poitrine vers le sol puis poussez pour revenir en position de départ. Cette fiche décrit la pompe standard, distincte de ses nombreuses variantes.","startPosition":"Placez-vous en planche haute, les mains légèrement plus écartées que les épaules et les doigts dirigés vers l’avant.\nFormez une ligne droite des talons à la tête en engageant la sangle abdominale et les fessiers.\nFléchissez les coudes pour descendre la poitrine vers le sol.","outboundExecution":"Gardez les coudes à environ 45 degrés du buste.\nTouchez le sol avec la poitrine, ou approchez-vous à quelques centimètres selon votre mobilité.\nPoussez dans les mains jusqu’à tendre les bras, sans perdre l’alignement du corps.","returnExecution":"Réalisez 10 à 25 répétitions par série selon votre niveau.","adaptedVersion":"Pompe sur les genoux.\nPompe diamant.\nPompe inclinée.\nPompe déclinée.\nPompe archer.","tips":"Développe la force des pectoraux, des triceps et des épaules.\nRenforce le gainage et la stabilité des épaules.\nNe nécessite aucun matériel et peut se pratiquer partout.\nSe décline facilement en variantes plus simples ou plus difficiles.","errors":"Gardez la nuque neutre et le tronc gainé pendant tout le mouvement.\nRéduisez l'amplitude ou choisissez une variante inclinée si le bas du dos ou les épaules compensent.\nArrêtez l'exercice en cas de douleur aiguë au poignet, au coude ou à l'épaule.","isActive":true,"reviewStatus":"valide","translationStatus":"validated","media":[{"kind":"poster","uri":"docs/bibliotheque/strength/no-equipment/push-up/push-up-poster.webp","fileName":"push-up-poster.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":1,"loopCount":null,"sha256":"5d4d7094ae5a0c470f8eec6869a3ced8f55fb3b8b76f18debcbb8a1920dd61da","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"},{"kind":"animation","uri":"docs/bibliotheque/strength/no-equipment/push-up/push-up-animate.webp","fileName":"push-up-animate.webp","mimeType":"image/webp","width":360,"height":360,"frameCount":12,"loopCount":0,"sha256":"0c09953f530a7864ca95f766f7d0bc301824d14c6f3bcf806a2363efc2b6f632","status":"ready","updatedAt":"2026-08-12T00:00:00.000Z"}]}]
$acrea_exercises$::jsonb) as value(slug text, media jsonb)
)
insert into public.catalog_exercise_media (
  exercise_id, kind, uri, file_name, mime_type, width, height, frame_count,
  loop_count, sha256, source_url, status, updated_at
)
select exercise.id, asset->>'kind', asset->>'uri', asset->>'fileName',
       asset->>'mimeType', (asset->>'width')::integer, (asset->>'height')::integer,
       (asset->>'frameCount')::integer, nullif(asset->>'loopCount', '')::integer,
       asset->>'sha256', null, asset->>'status', (asset->>'updatedAt')::timestamptz
from exercise_seed value
join public.catalog_exercises exercise on exercise.slug = value.slug
cross join lateral jsonb_array_elements(value.media) asset;

