[{"code":"beta-main-air-squat","title":"Air Squat — séance principale","description":"Template beta généré depuis la fiche V2 validée de Air Squat.","exerciseSlug":"air-squat","phase":"main","isActive":true,"sourceStatus":"beta v1.00 — bibliothèque V2 validée","updatedAt":"2026-08-12T00:00:00.000Z","levels":[2,3,4,5]},{"code":"beta-main-burpee","title":"Burpee — séance principale","description":"Template beta généré depuis la fiche V2 validée de Burpee.","exerciseSlug":"burpee","phase":"main","isActive":true,"sourceStatus":"beta v1.00 — bibliothèque V2 validée","updatedAt":"2026-08-12T00:00:00.000Z","levels":[5,6,7,8]},{"code":"beta-main-lean-planche","title":"Lean Planche — séance principale","description":"Template beta généré depuis la fiche V2 validée de Lean Planche.","exerciseSlug":"lean-planche","phase":"main","isActive":true,"sourceStatus":"beta v1.00 — bibliothèque V2 validée","updatedAt":"2026-08-12T00:00:00.000Z","levels":[7,8,9]},{"code":"beta-main-lying-leg-raise","title":"Lying Leg Raise — séance principale","description":"Template beta généré depuis la fiche V2 validée de Lying Leg Raise.","exerciseSlug":"lying-leg-raise","phase":"main","isActive":true,"sourceStatus":"beta v1.00 — bibliothèque V2 validée","updatedAt":"2026-08-12T00:00:00.000Z","levels":[1,2,3]},{"code":"beta-main-mountain-climber","title":"Mountain Climber — séance principale","description":"Template beta généré depuis la fiche V2 validée de Mountain Climber.","exerciseSlug":"mountain-climber","phase":"main","isActive":true,"sourceStatus":"beta v1.00 — bibliothèque V2 validée","updatedAt":"2026-08-12T00:00:00.000Z","levels":[4,5,6]},{"code":"beta-main-push-up","title":"Pompe — séance principale","description":"Template beta généré depuis la fiche V2 validée de Pompe.","exerciseSlug":"push-up","phase":"main","isActive":true,"sourceStatus":"beta v1.00 — bibliothèque V2 validée","updatedAt":"2026-08-12T00:00:00.000Z","levels":[5,6,7,8]},{"code":"beta-warmup-lying-leg-raise","title":"Préparation — Lying Leg Raise","description":"Template beta de préparation rattaché à la fiche V2 validée.","exerciseSlug":"lying-leg-raise","phase":"warmup","isActive":true,"sourceStatus":"beta v1.00 — phases fixes validées","updatedAt":"2026-08-12T00:00:00.000Z","levels":[1]},{"code":"beta-cooldown-lying-leg-raise","title":"Retour au calme — Lying Leg Raise","description":"Template beta de retour au calme rattaché à la fiche V2 validée.","exerciseSlug":"lying-leg-raise","phase":"cooldown","isActive":true,"sourceStatus":"beta v1.00 — phases fixes validées","updatedAt":"2026-08-12T00:00:00.000Z","levels":[1]}]
$acrea_templates$::jsonb) as value(
